import { useEffect } from 'react';
import { content, getCommander, getUnit } from '../content';
import { commanderArtUrl } from '../render/unitArt';
import { ACHAEMENID_MOTIFS, motifSetName, motifsAt } from '../ui/motifs/catalogue';
import { LotusFrieze, Merlons, RosetteBand } from '../ui/motifs/Ornament';
import { UnitGlyph } from '../ui/UnitGlyph';
import './looklab.css';

/**
 * DEV TOOL — reachable at `?looklab`, never linked from the game.
 *
 * Phase 0 of docs/DESIGN-GAME-LOOK.md: the font test, and one screen (the
 * lobby) mocked in the Achaemenid motif set, so the direction can be judged on
 * a real screen before anything in the game changes. Nothing here is wired
 * into play.
 *
 * Fonts load from Google Fonts for this test only. If a face is chosen it gets
 * self-hosted in the bundle — the game is played from Iran, where Google's
 * servers cannot be relied on.
 */

const FONTS_URL =
  'https://fonts.googleapis.com/css2?family=Lalezar&family=Reem+Kufi:wght@500;700&family=Vazirmatn:wght@400;600;800&family=Nunito:wght@400;800&display=swap';

const SYSTEM = 'system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';

const SPECIMENS = [
  {
    id: 'today',
    label: 'What ships today',
    note: 'The device’s system font. The CSS names Nunito, but Nunito is never loaded — so every phone shows its own font.',
    display: SYSTEM,
    text: SYSTEM,
  },
  { id: 'nunito', label: 'Nunito, as the CSS intended', note: 'The rounded sans of learning apps.', display: 'Nunito', text: 'Nunito' },
  {
    id: 'lalezar',
    label: 'Lalezar + Vazirmatn',
    note: 'Candidate. A heavy Persian-designed display face with Latin and Persian script; Vazirmatn for reading.',
    display: 'Lalezar',
    text: 'Vazirmatn',
  },
  {
    id: 'reemkufi',
    label: 'Reem Kufi + Vazirmatn',
    note: 'Candidate for Islamic-era headings: Kufic-derived geometry.',
    display: '"Reem Kufi"',
    text: 'Vazirmatn',
  },
];

/** The arena the mock lobby stands in: the end of the empire, so every Achaemenid motif is in period. */
const MOCK_ARENA = 'persian-gates';

export default function LookLab() {
  useEffect(() => {
    if (document.getElementById('looklab-fonts')) return;
    const link = document.createElement('link');
    link.id = 'looklab-fonts';
    link.rel = 'stylesheet';
    link.href = FONTS_URL;
    document.head.appendChild(link);
  }, []);

  const karkish = getUnit('persian-archer');
  const arena = content.arenas.find((a) => a.slug === MOCK_ARENA)!;
  const inPeriod = motifsAt(arena.yearNumeric);
  const deck = ['persian-archer', 'spara-bearer', 'median-spearman', 'persian-cavalry'].map(getUnit);
  const commanders = ['cyrus', 'astyages'].map(getCommander);

  return (
    <div className="looklab">
      <header className="looklab__intro">
        <h1>Look lab</h1>
        <p>
          Phase 0 of <code>docs/DESIGN-GAME-LOOK.md</code>. Nothing on this page is in the game yet — it is here to be
          judged.
        </p>
      </header>

      {/* ------------------------------------------------------------ fonts */}
      <section>
        <h2>1 · The font test</h2>
        <div className="looklab__specimens">
          {SPECIMENS.map((s) => (
            <article
              key={s.id}
              className="spec"
              style={{ ['--ld' as string]: s.display, ['--lt' as string]: s.text }}
            >
              <p className="spec__label">{s.label}</p>
              <p className="spec__note">{s.note}</p>
              <h3 className="spec__title">PERSIA AT WAR</h3>
              <button type="button" className="spec__btn">
                BATTLE
              </button>
              <div className="spec__score">
                <span className="spec__round">ROUND 4 OF 7</span>
                <span className="spec__big">3 – 1</span>
              </div>
              <div className="spec__card">
                <strong>{karkish.name}</strong>
                <span className="spec__sub">{karkish.contingent}</span>
                <span className="spec__stats">
                  ATK <b>{karkish.atk}</b> DEF <b>{karkish.def}</b> HP <b>{karkish.hp}</b>
                </span>
              </div>
              <p className="spec__blurb">{karkish.blurb}</p>
              <p className="spec__fa" dir="rtl" lang="fa">
                کوروش بزرگ · ۵۵۹ پیش از میلاد
              </p>
            </article>
          ))}
        </div>
      </section>

      {/* ------------------------------------------------------- the mock */}
      <section>
        <h2>2 · One screen, mocked: the lobby at {arena.name}</h2>
        <p className="looklab__lede">
          {arena.year} — motif set: <strong>{motifSetName(arena.yearNumeric)}</strong>. Display: Lalezar. Text:
          Vazirmatn. Colours: the game’s own Achaemenid palette.
        </p>
        <div className="looklab__mockwrap">
          <div className="mock">
            <div className="mock__top">
              <span className="mock__player">
                <span className="mock__avatar" aria-hidden="true" />
                Swift Lion
              </span>
              <span className="mock__purse">
                <span>◆ 25</span>
                <span>● 500</span>
              </span>
            </div>

            <Merlons height={14} className="mock__merlons" />
            <div className="mock__plate">
              <span className="mock__kicker">ARENA {arena.id}</span>
              <h3 className="mock__arena">{arena.name}</h3>
              <p className="mock__when">{arena.year}</p>
              <div className="mock__trophy">
                <span>🏆 4,120</span>
                <div className="mock__bar">
                  <i style={{ width: '64%' }} />
                </div>
              </div>
            </div>
            <RosetteBand height={20} className="mock__rosettes" />

            <div className="mock__hero">
              <span>Hero art to commission</span>
              <strong>Lamassu of the Gate of All Nations</strong>
              <em>Human-headed winged bulls — not lions</em>
            </div>
            <RosetteBand height={20} className="mock__rosettes" />

            <button type="button" className="mock__battle">
              <Merlons height={10} className="mock__cap" />
              BATTLE
            </button>
            <div className="mock__pair">
              <button type="button" className="mock__tile">
                PRACTICE
              </button>
              <button type="button" className="mock__tile mock__tile--lapis">
                CHRONICLE
              </button>
            </div>

            <LotusFrieze height={18} className="mock__lotus" />

            <div className="mock__commanders">
              {commanders.map((c) => {
                const face = commanderArtUrl(c.id);
                return (
                  <div key={c.id} className={`mock__cmd${c.id === 'cyrus' ? ' is-on' : ''}`}>
                    <span className="mock__face">{face && <img src={face} alt="" />}</span>
                    <strong>{c.name}</strong>
                    <span>{c.epithet}</span>
                  </div>
                );
              })}
            </div>

            <div className="mock__deck">
              {deck.map((u) => (
                <span key={u.id} className="mock__slot">
                  <UnitGlyph kind={u.art.silhouette} size={34} unitId={u.id} />
                  <b>{u.name}</b>
                </span>
              ))}
            </div>

            <RosetteBand height={16} className="mock__rosettes mock__rosettes--nav" />
            <nav className="mock__nav">
              {['Bazaar', 'Army', 'Battle', 'Scrolls', 'Trophies'].map((t) => (
                <span key={t} className={t === 'Battle' ? 'is-on' : ''}>
                  {t}
                </span>
              ))}
            </nav>
          </div>

          <aside className="looklab__legend">
            <h3>What is on it, and why it is allowed here</h3>
            <p>
              A surface tied to a date may only use ornament that existed by that date. {arena.name} is {arena.year}, so
              the whole Achaemenid set is in period:
            </p>
            <ul>
              {inPeriod.map((m) => (
                <li key={m.id}>
                  <strong>{m.name}</strong> — {m.source}
                  {m.kind === 'figure' && <em> (figure: commissioned art, not drawn in code)</em>}
                  {m.note && <span className="looklab__warn"> {m.note}</span>}
                </li>
              ))}
            </ul>
          </aside>
        </div>
      </section>

      {/* ---------------------------------------------------- chronology */}
      <section>
        <h2>3 · Which arena gets which set</h2>
        <table className="looklab__chrono">
          <thead>
            <tr>
              <th>Arena</th>
              <th>Date</th>
              <th>Motif set</th>
              <th>Motifs in period</th>
            </tr>
          </thead>
          <tbody>
            {content.arenas.map((a) => (
              <tr key={a.id}>
                <td>
                  {a.id} · {a.name}
                </td>
                <td>{a.year}</td>
                <td>{motifSetName(a.yearNumeric)}</td>
                <td>{motifsAt(a.yearNumeric).length} of {ACHAEMENID_MOTIFS.length}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </div>
  );
}
