import { useId } from 'react';

/**
 * Achaemenid pattern motifs, drawn in code.
 *
 * Each is an SVG <pattern> that TILES across whatever width it is given — a
 * wider screen gets more rosettes, never fatter ones, the lesson the cuneiform
 * frame strip already learned. Colours come from CSS variables so one drawing
 * serves every era's palette:
 *   --m-fg      the carved or glazed figure
 *   --m-accent  a centre or highlight
 *   --m-line    the band's ruled edges
 *
 * These are ORNAMENT, abstracted from the originals (see catalogue.ts for where
 * each comes from and from when); they are not reproductions and never
 * captioned as one.
 */

const fg = { fill: 'var(--m-fg, #e2c06a)' };
const accent = { fill: 'var(--m-accent, #1f8f8a)' };
const line = { stroke: 'var(--m-line, #e2c06a)' };

/** Twelve-petal rosettes in a ruled band — the Apadana staircase borders. */
export function RosetteBand({ height = 22, className }: { height?: number; className?: string }) {
  const id = useId().replace(/:/g, '');
  const h = height;
  const r = h * 0.36;
  const c = h / 2;
  return (
    <svg className={className} width="100%" height={h} aria-hidden="true" role="presentation">
      <defs>
        <pattern id={`ros${id}`} width={h} height={h} patternUnits="userSpaceOnUse">
          <line x1={0} y1={0.5} x2={h} y2={0.5} strokeWidth={1} style={line} />
          <line x1={0} y1={h - 0.5} x2={h} y2={h - 0.5} strokeWidth={1} style={line} />
          {Array.from({ length: 12 }, (_, k) => (
            <ellipse
              key={k}
              cx={c}
              cy={c - r * 0.52}
              rx={r * 0.2}
              ry={r * 0.46}
              transform={`rotate(${k * 30} ${c} ${c})`}
              style={fg}
            />
          ))}
          <circle cx={c} cy={c} r={r * 0.24} style={accent} />
        </pattern>
      </defs>
      <rect width="100%" height={h} fill={`url(#ros${id})`} />
    </svg>
  );
}

/** Open lotus and closed bud, alternating on a running stem — the Persepolis frieze. */
export function LotusFrieze({ height = 20, className }: { height?: number; className?: string }) {
  const id = useId().replace(/:/g, '');
  const h = height;
  const w = h * 2;
  const base = h * 0.92;
  const lx = w * 0.25;
  const bx = w * 0.75;
  return (
    <svg className={className} width="100%" height={h} aria-hidden="true" role="presentation">
      <defs>
        <pattern id={`lot${id}`} width={w} height={h} patternUnits="userSpaceOnUse">
          {/* The running stem: lotus to bud, and bud on to the next tile's lotus. */}
          <path
            d={`M${lx},${base - h * 0.1} Q${(lx + bx) / 2},${base + h * 0.1} ${bx},${base - h * 0.1} Q${(bx + w + lx) / 2},${base + h * 0.1} ${w + lx},${base - h * 0.1}`}
            fill="none"
            strokeWidth={Math.max(1, h * 0.06)}
            style={line}
          />
          {/* Open lotus: a tall centre petal between two that curl outward. */}
          <path
            d={`M${lx},${base - h * 0.14} Q${lx - h * 0.13},${base - h * 0.5} ${lx},${base - h * 0.9} Q${lx + h * 0.13},${base - h * 0.5} ${lx},${base - h * 0.14} Z`}
            style={fg}
          />
          <path
            d={`M${lx},${base - h * 0.18} Q${lx - h * 0.34},${base - h * 0.3} ${lx - h * 0.4},${base - h * 0.74} Q${lx - h * 0.16},${base - h * 0.5} ${lx},${base - h * 0.18} Z`}
            style={fg}
          />
          <path
            d={`M${lx},${base - h * 0.18} Q${lx + h * 0.34},${base - h * 0.3} ${lx + h * 0.4},${base - h * 0.74} Q${lx + h * 0.16},${base - h * 0.5} ${lx},${base - h * 0.18} Z`}
            style={fg}
          />
          <circle cx={lx} cy={base - h * 0.14} r={h * 0.08} style={accent} />
          {/* Closed bud. */}
          <path
            d={`M${bx},${base - h * 0.14} Q${bx - h * 0.15},${base - h * 0.42} ${bx},${base - h * 0.7} Q${bx + h * 0.15},${base - h * 0.42} ${bx},${base - h * 0.14} Z`}
            style={fg}
          />
        </pattern>
      </defs>
      <rect width="100%" height={h} fill={`url(#lot${id})`} />
    </svg>
  );
}

/** Stepped merlons on a coping — the crown of the Persepolis staircase parapets. */
export function Merlons({ height = 16, className }: { height?: number; className?: string }) {
  const id = useId().replace(/:/g, '');
  const h = height;
  const coping = Math.max(2, h * 0.16);
  const top = h - coping;
  const w = h * 1.1;
  const u = w / 8;
  const step = top / 3;
  const pts = [
    [u, top],
    [u, top - step],
    [2 * u, top - step],
    [2 * u, top - 2 * step],
    [3 * u, top - 2 * step],
    [3 * u, 0],
    [5 * u, 0],
    [5 * u, top - 2 * step],
    [6 * u, top - 2 * step],
    [6 * u, top - step],
    [7 * u, top - step],
    [7 * u, top],
  ]
    .map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`)
    .join(' ');
  return (
    <svg className={className} width="100%" height={h} aria-hidden="true" role="presentation">
      <defs>
        <pattern id={`mer${id}`} width={w} height={h} patternUnits="userSpaceOnUse">
          <polygon points={pts} style={fg} />
          <rect x={0} y={top} width={w} height={coping} style={fg} />
        </pattern>
      </defs>
      <rect width="100%" height={h} fill={`url(#mer${id})`} />
    </svg>
  );
}
