/**
 * The Achaemenid motif catalogue — every ornament the game may draw, with WHEN
 * it existed.
 *
 * The rule (Alireza, 26 Sep 2026): Persepolis ornament in Anshan is an
 * anachronism. Persepolis was founded under Darius I around 518 BCE, after
 * Cyrus died in 530; the Gate of All Nations with its lamassu is Xerxes'. So a
 * surface that belongs to a date — an arena's board border, its splash — may
 * only use motifs that existed by that date. Game-wide surfaces (the cover, the
 * logo) are not dated and may use any motif of the era they stand for.
 *
 * `from` is deliberately coarse: a reign or a founding, never a false exact
 * year. Where a date is approximate the source line says "c.".
 */

export type MotifKind = 'pattern' | 'figure';

export interface Motif {
  id: string;
  name: string;
  /** Where it is actually found, and under whom. */
  source: string;
  /** Earliest year it existed (negative = BCE). */
  from: number;
  /** A `pattern` is drawn in code as SVG; a `figure` needs commissioned art. */
  kind: MotifKind;
  /** Anything a caption must not get wrong. */
  note?: string;
}

