/** The motifs a surface dated to `year` may use. */
export function motifsAt(year: number): Motif[] {
  return ACHAEMENID_MOTIFS.filter((m) => year >= m.from);
}

/** A short name for the set a date gets, for labels. */
export function motifSetName(year: number): string {
  const ids = new Set(motifsAt(year).map((m) => m.id));
  if (ids.has('lamassu')) return 'Persepolis, complete';
  if (ids.has('rosette-band')) return 'Persepolis (Darius)';
  if (ids.has('archers-frieze')) return 'Susa (early Darius)';
  if (ids.has('bichrome-stone')) return 'Pasargadae (Cyrus)';
  return 'Before Pasargadae — to research';
}
